// accent colours the border or text of the focused component.
const accent = lipgloss.Color("#bd93f9")

// Focus ring order (tab / shift+tab).
const (
	focusNameInput = iota
	focusSubmitBtn
	focusAgree
	focusColor
	focusResults
	focusFiles
	focusPages
	focusCount
)

type model struct {
	ui         *Ui // the store and the program API
	winW, winH int // terminal size
	focus      int // index into the focus ring
	hits       []hit // rectangles of the interactive components, filled by View (mouse)
	dlg        hit   // rectangle of the error dialog (zero if none)
	scroll     int   // rows the root content is scrolled by
	scrollMax  int   // largest scroll offset (content height - view height)
	viewH      int   // height of the scrolled area
	contentY   int   // screen row where the scrolled area starts
	ddTag      string // select whose dropdown is open ("" if none)
	ddCur      int   // highlighted option of that dropdown
	nameInput textinput.Model
	progress progress.Model
	results table.Model
	resultsVer uint64 // store version last copied into the table
}

// c is the store entry of a component.
func (m *model) c(tag string) *Comp { return m.ui.Comp(tag) }

func newModel(ui *Ui) *model {
	m := &model{ui: ui}
	m.nameInput = textinput.New()
	m.nameInput.Prompt = ""
	m.nameInput.Width = 15
	m.nameInput.TextStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("#f8f8f2"))
	m.progress = progress.New(progress.WithSolidFill("#f8f8f2"), progress.WithWidth(18))
	m.results = table.New(
		table.WithStyles(tableStyles("#f8f8f2")),
		table.WithHeight(3),
		table.WithFocused(false),
	)
	m.pull()
	return m
}

func (m *model) Init() tea.Cmd {
	m.ui.SetReady()
	return tea.Batch(m.initialFocus(), textinput.Blink)
}

func (m *model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	m.pull()
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.winW, m.winH = msg.Width, msg.Height
		return m, nil
	case refreshMsg:
		return m, nil
	case frameMsg:
		msg.reply <- m.View()
		return m, nil
	case tea.KeyMsg:
		prev := m.focus
		next, cmd := m.updateKey(msg)
		if m.focus != prev {
			m.reveal()
		}
		return next, cmd
	case tea.MouseMsg:
		prev := m.focus
		cmd := m.updateMouse(msg)
		if m.focus != prev {
			m.reveal()
		}
		return m, cmd
	}
	return m, nil
}

func (m *model) updateKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	key := msg.String()
	switch key {
	case "ctrl+c":
		return m, tea.Quit
	case "ctrl+l":
		m.ui.ToggleLog()
		return m, nil
	}
	// The error dialog takes every key until it is closed.
	if len(m.ui.UnseenErrors()) > 0 {
		if key == "enter" || key == "esc" {
			m.ui.MarkErrorsSeen()
		}
		return m, nil
	}
	// An open dropdown takes the keys until it is closed.
	if m.ddTag != "" {
		m.dropdownKey(key)
		return m, nil
	}
	switch key {
	case "tab":
		return m, m.moveFocus(1)
	case "shift+tab":
		return m, m.moveFocus(-1)
	case "pgup", "pgdown", "home", "end":
		if !m.typing() && m.activeModal() == "" {
			m.scrollKey(key)
			return m, nil
		}
	case "esc":
		m.c("confirm").UserSet("open", false)
		return m, nil
	case "q":
		if !m.typing() {
			return m, tea.Quit
		}
	}
	return m, m.updateFocused(msg, key)
}

// typing reports whether the focused component takes text (so "q" does not quit).
func (m *model) typing() bool {
	switch m.focus {
	case focusNameInput:
		return m.c("name_input").State() == StateActive
	}
	return false
}

// updateFocused handles a key for the focused component. Muted, readonly and hidden
// components ignore the user (and send no events).
func (m *model) updateFocused(msg tea.KeyMsg, key string) tea.Cmd {
	if !m.focusable(m.focus) {
		return nil
	}
	switch m.focus {
	case focusNameInput:
		c := m.c("name_input")
		if c.State() != StateActive {
			return nil
		}
		before := m.nameInput.Value()
		var cmd tea.Cmd
		m.nameInput, cmd = m.nameInput.Update(msg)
		if after := m.nameInput.Value(); after != before {
			c.UserSet("value", after)
			c.Emit("change", after)
			m.ui.Defer(m.handleChange)
		}
		if key == "enter" {
			c.Emit("submit", m.nameInput.Value())
		}
		return cmd
	case focusSubmitBtn:
		c := m.c("submit_btn")
		if c.State() != StateActive {
			return nil
		}
		if key == "enter" || key == " " {
			c.Emit("click", nil)
			m.ui.Defer(m.handleClick)
		}
	case focusAgree:
		c := m.c("agree")
		if c.State() != StateActive {
			return nil
		}
		if key == "enter" || key == " " {
			v := !c.Bool("checked")
			c.UserSet("checked", v)
			c.Emit("change", v)
			m.ui.Defer(m.handleChange)
		}
	case focusColor:
		c := m.c("color")
		if c.State() != StateActive {
			return nil
		}
		if key == "enter" || key == " " || key == "down" {
			m.openDropdown(c.Tag())
		}
	case focusResults:
		c := m.c("results")
		if c.State() != StateActive {
			return nil
		}
		var cmd tea.Cmd
		m.results, cmd = m.results.Update(msg)
		return cmd
	case focusFiles:
		c := m.c("files")
		if c.State() != StateActive {
			return nil
		}
		switch key {
		case "up", "k":
			c.UserSet("selected", moveCursor(c.Int("selected"), -1, len(c.List("items"))))
		case "down", "j":
			c.UserSet("selected", moveCursor(c.Int("selected"), 1, len(c.List("items"))))
		case "enter", " ":
			c.Emit("select", c.Int("selected"))
			m.ui.Defer(m.handleSelect)
		}
	case focusPages:
		c := m.c("pages")
		if c.State() != StateActive {
			return nil
		}
		cur := c.Int("active_tab")
		next := cur
		switch key {
		case "left", "h":
			next = max(cur-1, 0)
		case "right", "l":
			next = min(cur+1, 2)
		}
		if next != cur {
			c.UserSet("active_tab", next)
			c.Emit("change", next)
		}
	}
	return nil
}

// moveFocus goes to the next component (d = 1) or the previous one (d = -1) that the
// user can use: hidden, muted and closed-modal components are skipped.
func (m *model) moveFocus(d int) tea.Cmd {
	i := m.focus
	for k := 0; k < focusCount; k++ {
		i = (i + d + focusCount) % focusCount
		if m.focusable(i) {
			return m.setFocus(i)
		}
	}
	return nil
}

func (m *model) focusable(i int) bool {
	switch i {
	case focusNameInput:
		return m.ui.Usable("name_input")
	case focusSubmitBtn:
		return m.ui.Usable("submit_btn")
	case focusAgree:
		return m.ui.Usable("agree")
	case focusColor:
		return m.ui.Usable("color")
	case focusResults:
		return m.ui.Usable("results")
	case focusFiles:
		return m.ui.Usable("files")
	case focusPages:
		return m.ui.Usable("pages")
	}
	return false
}

func (m *model) initialFocus() tea.Cmd {
	if !m.focusable(m.focus) {
		return m.moveFocus(1)
	}
	return m.applyFocus()
}

func (m *model) setFocus(i int) tea.Cmd {
	switch m.focus {
	case focusNameInput:
		m.nameInput.Blur()
	case focusResults:
		m.results.Blur()
	}
	m.focus = i
	return m.applyFocus()
}

func (m *model) applyFocus() tea.Cmd {
	switch m.focus {
	case focusNameInput:
		return m.nameInput.Focus()
	case focusResults:
		m.results.Focus()
	}
	return nil
}

// activeModal is the open modal on top ("" if none): while one is open, clicks only reach it.
func (m *model) activeModal() string {
	top := ""
	if m.ui.Open("confirm") {
		top = "confirm"
	}
	return top
}

// focusOn moves the focus to component i (no-op if it has it already).
func (m *model) focusOn(i int) tea.Cmd {
	if i == m.focus {
		return nil
	}
	return m.setFocus(i)
}

// updateMouse handles a mouse message: the error dialog first, then an open dropdown, then the
// open modal, then the UI. The wheel scrolls a list under the pointer, else the root content.
func (m *model) updateMouse(msg tea.MouseMsg) tea.Cmd {
	left := msg.Action == tea.MouseActionPress && msg.Button == tea.MouseButtonLeft
	if len(m.ui.UnseenErrors()) > 0 {
		if left && m.dlg.contains(msg.X, msg.Y) {
			m.ui.MarkErrorsSeen()
		}
		return nil
	}
	if m.ddTag != "" {
		if left {
			for i := len(m.hits) - 1; i >= 0; i-- {
				h := m.hits[i]
				if h.opt == 0 || !h.contains(msg.X, msg.Y) {
					continue
				}
				if h.opt > 0 {
					m.ddChoose(h.opt - 1)
				}
				return nil
			}
			m.ddTag = "" // a click outside closes it without a change
		}
		return nil
	}
	up := msg.Button == tea.MouseButtonWheelUp
	wheel := msg.Action == tea.MouseActionPress && (up || msg.Button == tea.MouseButtonWheelDown)
	if !left && !wheel {
		return nil
	}
	scope := m.activeModal()
	for i := len(m.hits) - 1; i >= 0; i-- {
		h := m.hits[i]
		if h.modal != scope || !h.contains(msg.X, msg.Y) {
			continue
		}
		if wheel {
			if cmd, moved := m.wheel(h, up); moved {
				return cmd
			}
			break
		}
		return m.click(h, msg.X-h.x, msg.Y-h.y)
	}
	if wheel && scope == "" {
		if up {
			m.scrollBy(-3)
		} else {
			m.scrollBy(3)
		}
	}
	return nil
}

// wheel moves the cursor of the list under the pointer; moved is false when it did not
// (not a list, or already at its end), so the caller scrolls the root instead.
func (m *model) wheel(h hit, up bool) (tea.Cmd, bool) {
	c := m.c(h.tag)
	if c.State() != StateActive || !m.focusable(h.focus) {
		return nil, false
	}
	pos := func() int {
		switch h.focus {
		case focusResults:
			return m.results.Cursor()
		case focusFiles:
			return c.Int("selected")
		}
		return -1
	}
	before := pos()
	if before < 0 {
		return nil, false
	}
	k := tea.KeyMsg{Type: tea.KeyDown}
	if up {
		k = tea.KeyMsg{Type: tea.KeyUp}
	}
	old := m.focus
	m.focus = h.focus
	cmd := m.updateFocused(k, k.String())
	m.focus = old
	return cmd, pos() != before
}

// click focuses the component under the pointer and does what Enter does (a row, a tab
// or an option is chosen by position). Muted, readonly and hidden components ignore it.
func (m *model) click(h hit, rx, ry int) tea.Cmd {
	c := m.c(h.tag)
	if c.State() != StateActive || !m.focusable(h.focus) {
		return nil
	}
	cmd := m.focusOn(h.focus)
	switch h.focus {
	case focusNameInput:
		return cmd
	case focusSubmitBtn:
		return tea.Batch(cmd, m.updateFocused(tea.KeyMsg{Type: tea.KeyEnter}, "enter"))
	case focusAgree:
		return tea.Batch(cmd, m.updateFocused(tea.KeyMsg{Type: tea.KeyEnter}, "enter"))
	case focusColor:
		m.openDropdown(h.tag)
		return cmd
	case focusResults:
		if r := tableRowAt(&m.results, ry-1-1); r >= 0 {
			m.results.SetCursor(r)
		}
		return tea.Batch(cmd, m.updateFocused(tea.KeyMsg{Type: tea.KeyEnter}, "enter"))
	case focusFiles:
		c.UserSet("selected", moveCursor(ry-1, 0, len(c.List("items"))))
		return tea.Batch(cmd, m.updateFocused(tea.KeyMsg{Type: tea.KeyEnter}, "enter"))
	case focusPages:
		if i := tabAt([]string{"⌂ Dashboard", "Agent ● ^1", "QA Team ^2"}, rx-0); i >= 0 && i != c.Int("active_tab") {
			c.UserSet("active_tab", i)
			c.Emit("change", i)
		}
		return cmd
	}
	return nil
}

// openDropdown shows the options of a select under its field.
func (m *model) openDropdown(tag string) {
	c := m.c(tag)
	opts := c.List("options")
	if len(opts) == 0 {
		return
	}
	m.ddTag, m.ddCur = tag, 0
	for i, o := range opts {
		if o == c.Str("value") {
			m.ddCur = i
		}
	}
}

// dropdownKey: Up/Down move, Enter or Space choose, Esc closes.
func (m *model) dropdownKey(key string) {
	n := len(m.c(m.ddTag).List("options"))
	switch key {
	case "up", "k":
		m.ddCur = max(m.ddCur-1, 0)
	case "down", "j":
		m.ddCur = min(m.ddCur+1, n-1)
	case "enter", " ":
		m.ddChoose(m.ddCur)
	case "esc":
		m.ddTag = ""
	}
}

// ddChoose closes the dropdown and sets the option; only a real change is an event.
func (m *model) ddChoose(i int) {
	tag := m.ddTag
	m.ddTag = ""
	c := m.c(tag)
	opts := c.List("options")
	if i < 0 || i >= len(opts) || opts[i] == c.Str("value") {
		return
	}
	c.UserSet("value", opts[i])
	c.Emit("change", opts[i])
	m.selectChanged(tag)
}

// selectChanged runs the editor handlers of a select whose value changed.
func (m *model) selectChanged(tag string) {
	if tag == "color" {
		m.ui.Defer(m.handleChange)
	}
}

// dropdownOverlay draws the open dropdown over the frame, under its field (above it if
// there is no room) and registers its rows in the click registry.
func (m *model) dropdownOverlay(out string) string {
	if m.ddTag == "" {
		return out
	}
	opts := m.c(m.ddTag).List("options")
	var anchor hit
	found := false
	for i := len(m.hits) - 1; i >= 0; i-- {
		if m.hits[i].tag == m.ddTag && m.hits[i].opt == 0 && m.hits[i].h > 0 {
			anchor, found = m.hits[i], true
			break
		}
	}
	if !found || len(opts) == 0 {
		m.ddTag = ""
		return out
	}
	inner := max(anchor.w-2, 1)
	for _, o := range opts {
		inner = max(inner, lipgloss.Width(line(o))+2)
	}
	rows := make([]string, len(opts))
	for i, o := range opts {
		st := lipgloss.NewStyle().Width(inner)
		if i == m.ddCur {
			st = st.Reverse(true)
		}
		rows[i] = st.Render(" " + line(o))
	}
	box := lipgloss.NewStyle().Border(lipgloss.NormalBorder()).BorderForeground(accent).Render(strings.Join(rows, "\n"))
	pw, ph := lipgloss.Width(box), lipgloss.Height(box)
	x, y := anchor.x, anchor.y+anchor.h
	if y+ph > lipgloss.Height(out) && anchor.y-ph >= 0 {
		y = anchor.y - ph
	}
	m.hits = append(m.hits, hit{focus: anchor.focus, tag: m.ddTag, modal: anchor.modal, opt: -1, x: x, y: y, w: pw, h: ph})
	for i := range opts {
		m.hits = append(m.hits, hit{focus: anchor.focus, tag: m.ddTag, modal: anchor.modal, opt: i + 1, x: x + 1, y: y + 1 + i, w: pw - 2, h: 1})
	}
	return overlay(out, x, y, box)
}

// pull copies changes made through the program API into the bubbles widgets.
func (m *model) pull() {
	{
		c := m.c("name_input")
		if v := c.Str("value"); v != m.nameInput.Value() {
			m.nameInput.SetValue(v)
		}
		m.nameInput.Placeholder = c.Str("placeholder")
	}
	{
		c := m.c("results")
		if v := c.Version(); v != m.resultsVer {
			m.resultsVer = v
			syncTable(&m.results, c.List("columns"), c.Rows("rows"))
		}
	}
}

