func (m *model) View() string {
	m.pull()
	m.hits = m.hits[:0]
	m.dlg = hit{}
	// The root fills the terminal (top-left); before the first size message it has the design size.
	w, h := 54, 46
	if m.winW > 0 && m.winH > 0 {
		w, h = m.winW, m.winH
	}
	logOn := m.ui.LogVisible()
	if logOn {
		h = max(h-logPanelHeight, 3)
	}
	out := m.renderDemo(0, 0, w, h)
	if m.ui.Open("confirm") {
		mx, my := max((w-40)/2, 0), max((h-12)/2, 0)
		out = overlay(out, mx, my, m.renderConfirm(mx, my))
	}
	out = m.dropdownOverlay(out)
	if logOn {
		out = lipgloss.JoinVertical(lipgloss.Left, out, logPanel(m.ui.LogEntries(), w))
	}
	if errs := m.ui.UnseenErrors(); len(errs) > 0 {
		out, m.dlg = withDialog(out, errorDialog(errs, w))
	}
	if m.winW > 0 && m.winH > 0 {
		out = frame(out, m.winW, m.winH, lipgloss.Left, lipgloss.Top)
	}
	return out
}

func (m *model) renderDemo(ox, oy, w, h int) string {
	iw, ih := max(w-2, 1), max(h-2, 1)
	start := len(m.hits)
	content := flexJoin(false, ox+1, oy+1, []flexItem{
		{m.renderStatus, 1, 1, m.ui.Hidden("status")},
		{m.renderNameInput, 1, 0, m.ui.Hidden("name_input")},
		{m.renderSubmitBtn, 1, 0, m.ui.Hidden("submit_btn")},
		{m.renderAgree, 1, 0, m.ui.Hidden("agree")},
		{func(x, y int) string { return m.renderColor(x, y, max(iw-2, 1)) }, 1, 0, m.ui.Hidden("color")},
		{m.renderProgress, 1, 0, m.ui.Hidden("progress")},
		{m.renderResults, 1, 0, m.ui.Hidden("results")},
		{func(x, y int) string { return m.renderFiles(x, y, max(iw-2, 1)) }, 1, 0, m.ui.Hidden("files")},
		{func(x, y int) string { return m.renderPages(x, y, max(iw-2, 1)) }, 1, 0, m.ui.Hidden("pages")},
		{m.renderPanel, 1, 0, m.ui.Hidden("panel")},
	})
	content = m.scrollWindow(content, start, oy+1, iw, ih)
	return lipgloss.NewStyle().Foreground(lipgloss.Color("#f8f8f2")).BorderStyle(lipgloss.NormalBorder()).BorderForeground(lipgloss.Color("#f8f8f2")).BorderTop(true).BorderRight(true).BorderBottom(true).BorderLeft(true).Render(frame(content, iw, ih, lipgloss.Left, lipgloss.Top))
}

func (m *model) renderStatus(ox, oy int) string {
	c := m.c("status")
	st := lipgloss.NewStyle().Foreground(lipgloss.Color("#f8f8f2"))
	content := c.Str("text")
	return st.Render(frame(content, growW(content, 5), growH(content, 1), lipgloss.Left, lipgloss.Top))
}

func (m *model) renderNameInput(ox, oy int) string {
	st := lipgloss.NewStyle().Foreground(lipgloss.Color("#f8f8f2")).BorderStyle(lipgloss.NormalBorder()).BorderForeground(lipgloss.Color("#f8f8f2")).BorderTop(true).BorderRight(true).BorderBottom(true).BorderLeft(true)
	if m.ui.Muted("name_input") {
		st = st.Faint(true)
	}
	if m.focus == focusNameInput {
		st = st.BorderForeground(accent)
	}
	return m.reg(focusNameInput, "name_input", "", ox, oy, st.Render(frame("  " + m.nameInput.View(), 18, 1, lipgloss.Left, lipgloss.Top)))
}

func (m *model) renderSubmitBtn(ox, oy int) string {
	c := m.c("submit_btn")
	st := lipgloss.NewStyle().Foreground(lipgloss.Color("#f8f8f2")).Bold(true).BorderStyle(lipgloss.RoundedBorder()).BorderForeground(lipgloss.Color("#f8f8f2")).BorderTop(true).BorderRight(true).BorderBottom(true).BorderLeft(true)
	if m.ui.Muted("submit_btn") {
		st = st.Faint(true)
	}
	// Button: Enter or Space presses it.
	if m.focus == focusSubmitBtn {
		st = st.BorderForeground(accent)
	}
	content := line(c.Str("label"))
	return m.reg(focusSubmitBtn, "submit_btn", "", ox, oy, st.Render(frame(content, growW(content, 14), growH(content, 1), lipgloss.Center, lipgloss.Center)))
}

func (m *model) renderAgree(ox, oy int) string {
	c := m.c("agree")
	st := lipgloss.NewStyle().Foreground(lipgloss.Color("#f8f8f2"))
	if m.ui.Muted("agree") {
		st = st.Faint(true)
	}
	if c.Bool("checked") {
		st = st.Foreground(lipgloss.Color("#50fa7b"))
	} else {
		st = st.Foreground(lipgloss.Color("#f8f8f2"))
	}
	if m.focus == focusAgree {
		st = st.Reverse(true)
	}
	mark := " "
	if c.Bool("checked") {
		mark = "✓"
	}
	content := "[" + mark + "] " + line(c.Str("label"))
	return m.reg(focusAgree, "agree", "", ox, oy, st.Render(frame(content, growW(content, 11), growH(content, 1), lipgloss.Left, lipgloss.Top)))
}

